function skyTexture(){const c=document.createElement('canvas');c.width=16;c.height=512;const x=c.getContext('2d'),g=x.createLinearGradient(0,0,0,512),a=currentMap.atmosphere;g.addColorStop(0,a.skyTop);g.addColorStop(.45,a.skyMid);g.addColorStop(1,a.skyLow);x.fillStyle=g;x.fillRect(0,0,16,512);const t=own(new THREE.CanvasTexture(c));t.colorSpace=THREE.SRGBColorSpace;return t}
function lights(){const frozen=currentMap.id==='frozen',desert=currentMap.id==='desert';scene.add(new THREE.HemisphereLight(frozen?0xd9f2ff:desert?0xffe2bd:0xc8e7ee,frozen?0x46545b:desert?0x6a442d:0x2d3027,frozen?1.8:1.55));scene.add(new THREE.AmbientLight(frozen?0x6b8490:desert?0x70503c:0x42606a,.34));const sun=new THREE.DirectionalLight(currentMap.atmosphere.sun,desert?4.6:frozen?3.45:4.15);sun.position.set(-18,30,14);sun.castShadow=quality==='high';sun.shadow.mapSize.set(1024,1024);sun.shadow.radius=2;Object.assign(sun.shadow.camera,{left:-38,right:38,top:28,bottom:-28,near:1,far:90});sun.shadow.bias=-.00065;scene.add(sun);const rim=new THREE.DirectionalLight(frozen?0xa8e9ff:0x64d7ff,1.05);rim.position.set(20,10,-17);scene.add(rim);const fill=new THREE.DirectionalLight(desert?0xff7a38:0xff7e56,desert?.42:.28);fill.position.set(8,5,18);scene.add(fill)}
function focusObjective(){const node=snapshot?.nodes?.[objectiveIndex++%(snapshot?.nodes?.length||1)];if(!node)return;center(node.x,node.y);desiredRange=Math.min(desiredRange,23);window.IronBridge?.notify(node.name||'Objective focused')}
function addControls(){const host=document.querySelector('.view-controls');if(!host)return;qualityButton=document.createElement('button');qualityButton.className='btn';qualityButton.id='quality-mode';qualityButton.textContent=`FX ${quality.toUpperCase()}`;qualityButton.onclick=()=>{const order=['low','balanced','high'];quality=order[(order.indexOf(quality)+1)%order.length];localStorage.setItem('iron-frontier-3d-quality',quality);window.IronBridge?.notify(`3D effects: ${quality}. Reopen 3D to apply.`);qualityButton.textContent=`FX ${quality.toUpperCase()}`};resetButton=document.createElement('button');resetButton.className='btn';resetButton.setAttribute('aria-label','Reset tactical camera');resetButton.title='Reset tactical camera';resetButton.textContent='HOME';resetButton.onclick=resetCamera;fitButton=document.createElement('button');fitButton.className='btn';fitButton.setAttribute('aria-label','Fit entire battlefield');fitButton.textContent='FIT';fitButton.onclick=fitBattlefield;focusButton=document.createElement('button');focusButton.className='btn';focusButton.setAttribute('aria-label','Focus selected units');focusButton.title='Keyboard shortcut: F';focusButton.textContent='FOCUS';focusButton.onclick=focusSelection;objectiveButton=document.createElement('button');objectiveButton.className='btn';objectiveButton.setAttribute('aria-label','Cycle objectives');objectiveButton.title='Keyboard shortcut: O';objectiveButton.textContent='OBJ';objectiveButton.onclick=focusObjective;host.append(qualityButton,objectiveButton,focusButton,fitButton,resetButton)}
function mount(){if(active)return;const host=document.querySelector('.arena-frame');if(!host)return;try{quality=chooseQuality();const state=window.IronBridge?.snapshot();currentMap=MAPS.get(state?.mapId);seedRng(state?.terrainSeed||currentMap.seed);scene=new THREE.Scene();scene.background=skyTexture();scene.fog=new THREE.FogExp2(currentMap.atmosphere.fog,currentMap.id==='desert'?.0085:currentMap.id==='frozen'?.0095:.008);renderer=new THREE.WebGLRenderer({antialias:quality==='high',powerPreference:'high-performance'});configureRenderer();canvas=renderer.domElement;canvas.id='world3d';canvas.dataset.map=currentMap.id;canvas.setAttribute('aria-label',`${currentMap.name} interactive 3D battlefield`);host.insertBefore(canvas,host.firstChild);host.classList.add('using-3d');camera=new THREE.PerspectiveCamera(39,1,.1,280);lights();terrain();active=true;bindCanvas();addControls();resize();resetCamera();window.addEventListener('resize',resize);sync(state,window.IronBridge?.selected());perfStart=performance.now();perf.frames=0;try{const gl=renderer.getContext(),ext=gl.getExtension('WEBGL_debug_renderer_info');perf.renderer=ext?gl.getParameter(ext.UNMASKED_RENDERER_WEBGL):gl.getParameter(gl.RENDERER)}catch{}clock.start();raf=requestAnimationFrame(loop)}catch(error){console.error('3D init failed',error);unmount(true);window.IronBridge?.notify('3D unavailable — continuing on the tactical map')}}
